"""Persistent key-value store backed by a single JSON document file (Approach A).

The entire store is one JSON object mapping keys to values. On open, the file is
loaded into memory (an empty file, or a missing one, is treated as an empty store).
Every mutation rewrites the file in place, so reads never touch disk after open and
the on-disk state always reflects the last completed write. No temp files, journals,
or side directories are ever created next to the data file.
"""

from __future__ import annotations

import json
import os


class Store:
    """A tiny persistent string -> string map living in one JSON file at ``path``."""

    def __init__(self, path: str) -> None:
        self._path = path
        self._closed = False
        self._data: dict[str, str] = self._load()
        if not os.path.exists(self._path):
            # Spec: the data file is created if missing.
            self._flush()

    # ------------------------------------------------------------------ I/O

    def _load(self) -> dict[str, str]:
        try:
            with open(self._path, "r", encoding="utf-8") as fh:
                raw = fh.read()
        except FileNotFoundError:
            return {}
        if not raw.strip():
            return {}
        data = json.loads(raw)
        if not isinstance(data, dict):
            raise ValueError(f"{self._path}: expected a JSON object at top level")
        for k, v in data.items():
            if not isinstance(k, str) or not isinstance(v, str):
                raise ValueError(f"{self._path}: keys and values must be strings")
        return data

    def _flush(self) -> None:
        # Rewrite the single data file in place. ensure_ascii=False keeps arbitrary
        # Unicode human-readable; sort_keys makes the file deterministic.
        with open(self._path, "w", encoding="utf-8") as fh:
            json.dump(self._data, fh, ensure_ascii=False, sort_keys=True, indent=2)
            fh.write("\n")
            fh.flush()
            os.fsync(fh.fileno())

    def _check_open(self) -> None:
        if self._closed:
            raise ValueError("Store is closed")

    # --------------------------------------------------------------- public

    def set(self, key: str, value: str) -> None:
        self._check_open()
        if not isinstance(key, str) or not isinstance(value, str):
            raise TypeError("key and value must be str")
        self._data[key] = value
        self._flush()

    def get(self, key: str) -> str | None:
        self._check_open()
        return self._data.get(key)

    def delete(self, key: str) -> bool:
        self._check_open()
        if key not in self._data:
            return False
        del self._data[key]
        self._flush()
        return True

    def keys(self) -> list[str]:
        self._check_open()
        return sorted(self._data)

    def close(self) -> None:
        if self._closed:
            return
        self._flush()
        self._closed = True

    # ---------------------------------------------------------- conveniences

    def __enter__(self) -> "Store":
        return self

    def __exit__(self, *exc: object) -> None:
        self.close()

    def __repr__(self) -> str:
        state = "closed" if self._closed else f"{len(self._data)} keys"
        return f"Store({self._path!r}, {state})"
EOF
